def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            # Fill the hollow interior in the object's bounding box with 2.
            for y in range(r0, r1+1):
                for x in range(c0, c1+1):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            # The top opening sends a horizontal ray leftward to the grid edge.
            top_holes = [x for x in range(c0, c1+1) if grid[r0][x] == 0]
            if top_holes and r0 > 0:
                for x in range(0, max(top_holes)+1):
                    if grid[r0-1][x] == 0:
                        out[r0-1][x] = 2
    return out
